import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-Elementwise-Binary-Operators.md","filePath":"manual-en/Matrix-Elementwise-Binary-Operators.md","lastUpdated":1785684581000}'),d={name:"manual-en/Matrix-Elementwise-Binary-Operators.md"};function i(p,e,s,n,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h4 id="_16-4-1-5-elementwise-binary-operators" tabindex="-1">16.4.1.5 Elementwise Binary Operators <a class="header-anchor" href="#_16-4-1-5-elementwise-binary-operators" aria-label="Permalink to &quot;16.4.1.5 Elementwise Binary Operators&quot;">​</a></h4><p>The elementwise binary operators require their operands to be matrices with the same dimensions. Alternatively, if one operand is a scalar, then its value is treated as if it were duplicated to the dimensions of the other operand. The result is a matrix of the same size as the operands, in which each element is the result of the applying the operator to the corresponding elements of the operands.</p><p>The elementwise binary operators are listed below.</p><ul><li>The arithmetic operators, for familiar arithmetic operations:</li></ul><p><code>+</code></p><p>Addition.</p><p><code>-</code></p><p>Subtraction.</p><p><code>*</code></p><p>Multiplication, if one operand is a scalar. (Otherwise this is matrix multiplication, described below.)</p><p><code>/</code> or <code>&amp;/</code></p><p>Division.</p><p><code>&amp;*</code></p><p>Multiplication.</p><p><code>&amp;**</code></p><p>Exponentiation.</p><ul><li>The relational operators, whose results are 1 when a comparison is true and 0 when it is false:</li></ul><p><code>&lt;</code> or <code>LT</code></p><p>Less than.</p><p><code>&lt;=</code> or <code>LE</code></p><p>Less than or equal.</p><p><code>=</code> or <code>EQ</code></p><p>Equal.</p><p><code>&gt;</code> or <code>GT</code></p><p>Greater than.</p><p><code>&gt;=</code> or <code>GE</code></p><p>Greater than or equal.</p><p><code>&lt;&gt;</code> or <code>~=</code> or <code>NE</code></p><p>Not equal.</p><ul><li>The logical operators, which treat positive operands as true and nonpositive operands as false. They yield 0 for false and 1 for true:</li></ul><p><code>AND</code></p><p>True if both operands are true.</p><p><code>OR</code></p><p>True if at least one operand is true.</p><p><code>XOR</code></p><p>True if exactly one operand is true.</p><p>Examples:</p><table tabindex="0"><thead><tr><th>1 + 2</th><th>⇒</th><th>3</th></tr></thead><tbody><tr><td>1 + {3; 4}</td><td>⇒</td><td>{4; 5}</td></tr><tr><td>{66, 77; 88, 99} + 5</td><td>⇒</td><td>{71, 82; 93, 104}</td></tr><tr><td>{4, 8; 3, 7} + {1, 0; 5, 2}</td><td>⇒</td><td>{5, 8; 8, 9}</td></tr><tr><td>{1, 2; 3, 4} &lt; {4, 3; 2, 1}</td><td>⇒</td><td>{1, 1; 0, 0}</td></tr><tr><td>{1, 3; 2, 4} &gt;= 3</td><td>⇒</td><td>{0, 1; 0, 1}</td></tr><tr><td>{0, 0; 1, 1} AND {0, 1; 0, 1}</td><td>⇒</td><td>{0, 0; 0, 1}</td></tr></tbody></table>',38)])])}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
